58. type (
59. 	// ContainerWaiter contains channels to wait on the termination of a running container.
60. 	// Results on the Waiter channel indicate changes in container state, while results on the
61. 	// Errs channel indicate failures to watch for updates.
62. 	ContainerWaiter struct {
63. 		Waiter <-chan dcontainer.ContainerWaitOKBody
64. 		Errs   <-chan error
65. 	}
