73. // Client wraps the Docker client, augmenting it with a few higher level convenience APIs.
74. type Client struct {
75. 	// Configuration details. Set during initialization, never modified afterwards.
76. 	credentialStores map[string]*credentialStore
77. 	authConfigs      map[string]types.AuthConfig
78. 
79. 	// System dependencies. Also set during initialization, never modified afterwards.
80. 	cl  *client.Client
81. 	log *logrus.Entry
82. }
