84. // NewClient populates credentials from the Docker Daemon config and returns a new Client that uses
85. // them.
86. func NewClient(cl *client.Client) *Client {
87. 	d := &Client{
88. 		cl:  cl,
89. 		log: logrus.WithField("component", "docker-client"),
90. 	}
91. 
92. 	stores, auths, err := processDockerConfig()
93. 	if err != nil {
94. 		d.log.Infof("couldn't process ~/.docker/config.json %v", err)
95. 	}
96. 	if len(stores) == 0 {
97. 		d.log.Info("can't find any docker credential stores, continuing without them")
98. 	}
99. 	if len(auths) == 0 {
100. 		d.log.Info("can't find any auths in ~/.docker/config.json, continuing without them")
101. 	}
102. 	d.credentialStores, d.authConfigs = stores, auths
103. 
104. 	// hack: docker client library is not thread-safe when negotiating API Version
105. 	d.cl.NegotiateAPIVersion(context.TODO())
106. 	return d
107. }
108. 
109. // Inner returns the underlying Docker client, to be used sparingly.
110. // TODO(DET-8628): Consolidate around usage of the wrapper client, remove this.
111. func (d *Client) Inner() *client.Client {
112. 	return d.cl
113. }
