115. // ReattachContainer looks for a single running or terminated container that matches the given
116. // filters and returns whether it can be reattached or has terminated.
117. func (d *Client) ReattachContainer(
118. 	ctx context.Context,
119. 	id cproto.ID,
120. ) (*Container, *aproto.ExitCode, error) {
121. 	filter := LabelFilter(ContainerIDLabel, id.String())
122. 	containers, err := d.cl.ContainerList(ctx, types.ContainerListOptions{Filters: filter})
123. 	if err != nil {
124. 		return nil, nil, fmt.Errorf("while reattaching container: %w", err)
125. 	}
126. 
127. 	if len(containers) > 1 {
128. 		return nil, nil, errors.New("reattach filters matched more than one container")
129. 	}
130. 
131. 	for _, cont := range containers {
132. 		// Subscribe to termination notifications first, to not miss immediate exits.
133. 		waiter, errs := d.cl.ContainerWait(ctx, cont.ID, dcontainer.WaitConditionNextExit)
134. 
135. 		// Restore containerInfo.
136. 		containerInfo, err := d.cl.ContainerInspect(ctx, cont.ID)
137. 		if err != nil {
138. 			return nil, nil, fmt.Errorf("inspecting reattached container: %w", err)
139. 		}
140. 
141. 		// Check if container has exited while we were trying to reattach it.
142. 		if !containerInfo.State.Running {
143. 			return nil, ptrs.Ptr(aproto.ExitCode(containerInfo.State.ExitCode)), nil
144. 		}
145. 		return &Container{ //nolint: staticcheck // We mean to terminate this loop.
146. 			ContainerInfo: containerInfo,
147. 			ContainerWaiter: ContainerWaiter{
148. 				Waiter: waiter,
149. 				Errs:   errs,
150. 			},
151. 		}, nil, nil
152. 	}
153. 	return nil, nil, nil
154. }
