156. // PullImage describes a request to pull an image.
157. type PullImage struct {
158. 	Name      string
159. 	ForcePull bool
160. 	Registry  *types.AuthConfig
161. }
162. 
163. // PullImage pulls an image according to the given request and credentials initialized at client
164. // creation from the Daemon config or credentials helpers configured there. It takes a
165. // caller-provided channel on which docker events are sent. Slow receivers will block the call.
166. func (d *Client) PullImage(ctx context.Context, req PullImage, p events.Publisher[Event]) error {
167. 	ref, err := reference.ParseNormalizedNamed(req.Name)
168. 	if err != nil {
169. 		return fmt.Errorf("error parsing image name %s: %w", req.Name, err)
170. 	}
171. 	ref = reference.TagNameOnly(ref)
172. 	switch _, _, err = d.cl.ImageInspectWithRaw(ctx, ref.String()); {
173. 	case req.ForcePull:
174. 		if err != nil {
175. 			break
176. 		}
177. 
178. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
179. 			"image present, but force_pull_image is set; checking for updates: %s",
180. 			ref.String(),
181. 		))); err != nil {
182. 			return err
183. 		}
184. 	case client.IsErrNotFound(err):
185. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
186. 			"image not found, pulling image: %s", ref.String(),
187. 		))); err != nil {
188. 			return err
189. 		}
190. 	case err != nil:
191. 		return fmt.Errorf("error checking if image exists %s: %w", ref.String(), err)
192. 	default:
193. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
194. 			"image already found, skipping pull phase: %s",
195. 			ref.String(),
196. 		))); err != nil {
197. 			return err
198. 		}
199. 		return nil
200. 	}
201. 
202. 	if err = p.Publish(ctx, NewBeginStatsEvent(ImagePullStatsKind)); err != nil {
203. 		return err
204. 	}
205. 	defer func() {
206. 		if scErr := p.Publish(ctx, NewEndStatsEvent(ImagePullStatsKind)); scErr != nil {
207. 			d.log.WithError(scErr).Warn("did not send image pull done stats")
208. 		}
209. 	}()
210. 
211. 	auth, err := d.getDockerAuths(ctx, ref, req.Registry, p)
212. 	if err != nil {
213. 		return fmt.Errorf("could not get docker authentication: %w", err)
214. 	}
215. 
216. 	authString, err := registryToString(*auth)
217. 	if err != nil {
218. 		return fmt.Errorf("error encoding docker credentials: %w", err)
219. 	}
220. 
221. 	logs, err := d.cl.ImagePull(ctx, ref.String(), types.ImagePullOptions{
222. 		All:          false,
223. 		RegistryAuth: authString,
224. 	})
225. 	if err != nil {
226. 		return errors.Wrapf(err, "error pulling image: %s", ref.String())
227. 	}
228. 	defer func() {
229. 		if err = logs.Close(); err != nil {
230. 			d.log.WithError(err).Error("error closing log stream")
231. 		}
232. 	}()
233. 
234. 	if err = d.sendPullLogs(ctx, logs, p); err != nil {
235. 		return fmt.Errorf("error processing pull log stream: %w", err)
236. 	}
237. 	return nil
238. }
